import{_ as l,o as a,c as r,a3 as e}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"2025 路线图","description":"Wheel.OS 和 Wheel.App 的版本功能、工具与运营能力规划。","frontmatter":{"title":"2025 路线图","description":"Wheel.OS 和 Wheel.App 的版本功能、工具与运营能力规划。","status":"计划能力","content_type":"roadmap","keywords":["WheelOS","路线图","Wheel.OS","Wheel.App","计划能力"]},"headers":[],"relativePath":"roadmap/2025.md","filePath":"roadmap/2025.md","lastUpdated":1794216847000}'),o={name:"roadmap/2025.md"};function i(n,t,s,h,d,g){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="自动驾驶系统版本发布路线图" tabindex="-1">自动驾驶系统版本发布路线图 <a class="header-anchor" href="#自动驾驶系统版本发布路线图" aria-label="Permalink to &quot;自动驾驶系统版本发布路线图&quot;">​</a></h1><blockquote><p>本页描述规划目标，不代表所有功能已经交付或完成真实车辆验证。</p></blockquote><h2 id="wheel-os-版本计划" tabindex="-1">Wheel.OS 版本计划 <a class="header-anchor" href="#wheel-os-版本计划" aria-label="Permalink to &quot;Wheel.OS 版本计划&quot;">​</a></h2><h3 id="版本-12-31" tabindex="-1">版本 12.31 <a class="header-anchor" href="#版本-12-31" aria-label="Permalink to &quot;版本 12.31&quot;">​</a></h3><h4 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h4><ul><li><strong>核心中间件：</strong> 支持核心功能模块并优化稳定性。</li><li><strong>Common_msgs 消息接口：</strong> 提供标准消息接口，支持模块间高效通信。</li><li><strong>传感器驱动：</strong> 增强多种传感器的支持与兼容性。</li><li><strong>车辆底盘：</strong> 支持底盘控制与调试，提高适配能力。</li></ul><h4 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h4><ul><li><strong>Aconf 配置管理：</strong> 支持灵活的模块配置加载。</li><li><strong>Cviz 数据可视化：</strong> 实时显示自动驾驶系统关键数据。</li><li><strong>DBC_tool 底盘适配：</strong> 优化车辆底盘适配流程并提高易用性。</li><li><strong>底盘调试工具：</strong> 支持底盘系统调试和性能优化。</li></ul><h2 id="wheel-app-版本计划" tabindex="-1">Wheel.App 版本计划 <a class="header-anchor" href="#wheel-app-版本计划" aria-label="Permalink to &quot;Wheel.App 版本计划&quot;">​</a></h2><h3 id="版本-2-28" tabindex="-1">版本 2.28 <a class="header-anchor" href="#版本-2-28" aria-label="Permalink to &quot;版本 2.28&quot;">​</a></h3><h4 id="功能-1" tabindex="-1">功能 <a class="header-anchor" href="#功能-1" aria-label="Permalink to &quot;功能&quot;">​</a></h4><ul><li><strong>定位：</strong> 提供基础定位能力。</li><li><strong>感知：</strong> 建立感知模块基础。</li><li><strong>预测：</strong> 支持动态目标的基础行为预测。</li><li><strong>规划：</strong> 实现初始路径规划功能。</li><li><strong>控制：</strong> 提供车辆控制能力。</li></ul><h4 id="工具-1" tabindex="-1">工具 <a class="header-anchor" href="#工具-1" aria-label="Permalink to &quot;工具&quot;">​</a></h4><ul><li><strong>传感器标定：</strong> 提供传感器初始化和标定工具。</li><li><strong>传感器时间同步：</strong> 解决多传感器同步问题。</li><li><strong>车辆动力学标定：</strong> 支持车辆动力学相关参数标定。</li><li><strong>Carla 集成：</strong> 通过桥接工具与 Carla 仿真器集成。</li></ul><h3 id="版本-6-30" tabindex="-1">版本 6.30 <a class="header-anchor" href="#版本-6-30" aria-label="Permalink to &quot;版本 6.30&quot;">​</a></h3><h4 id="功能-2" tabindex="-1">功能 <a class="header-anchor" href="#功能-2" aria-label="Permalink to &quot;功能&quot;">​</a></h4><ul><li><strong>中间件性能优化：</strong> 优化中间件模块运行性能。</li><li><strong>硬件适配：</strong><ul><li>支持 Horizon J6 硬件平台。</li><li>支持 NX5 硬件适配。</li></ul></li><li><strong>定位：</strong><ul><li>提升定位模块性能并支持室内定位。</li><li>实现多传感器融合定位。</li></ul></li><li><strong>感知：</strong><ul><li>优化感知模块性能。</li><li>实现语义分割能力。</li><li>建立稳健的开发流程。</li></ul></li><li><strong>预测：</strong> 提升动态环境中的行为预测能力。</li><li><strong>规划：</strong><ul><li>提供不依赖高精度地图的规划能力。</li><li>引入基于路径行为树的决策。</li></ul></li><li><strong>控制：</strong> 持续优化车辆控制系统。</li></ul><h4 id="运营" tabindex="-1">运营 <a class="header-anchor" href="#运营" aria-label="Permalink to &quot;运营&quot;">​</a></h4><ul><li><strong>功能安全：</strong> 推进系统功能安全相关工作。</li><li><strong>调度系统：</strong> 实现状态监控和任务调度能力。</li><li><strong>远程驾驶：</strong> 通过高级指令实现远程车辆控制。</li></ul><h4 id="工具-2" tabindex="-1">工具 <a class="header-anchor" href="#工具-2" aria-label="Permalink to &quot;工具&quot;">​</a></h4><ul><li><strong>车辆动力学建模：</strong> 支持基于车辆参数建立动力学模型。</li></ul><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>功能</th><th>工具</th><th>其他模块</th></tr></thead><tbody><tr><td><strong>Wheel.OS 12.31</strong></td><td>核心中间件、Common_msgs、驱动、车辆</td><td>Aconf、Cviz、DBC_tool、底盘调试</td><td>无</td></tr><tr><td><strong>Wheel.App 2.28</strong></td><td>定位、感知、预测、规划、控制</td><td>传感器标定、时间同步、动力学标定、Carla Bridge</td><td>无</td></tr><tr><td><strong>Wheel.App 6.30</strong></td><td>中间件优化、硬件适配、定位增强、感知优化、预测、规划、控制</td><td>车辆动力学建模</td><td>功能安全、调度系统、远程驾驶</td></tr></tbody></table><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>各版本功能按增量优先级推进，用于保持系统稳定性和性能优化。</li><li>工具模块会根据功能需求持续迭代。</li><li>运营模块将在后续版本逐步完善，用于支持系统安全和运营管理。</li></ul>',25)])])}const p=l(o,[["render",i]]);export{c as __pageData,p as default};
